     ```typescript
     /** Canonical feature branch name: `feature/<featureId>` */
     export function featureBranchName(featureId: string): string {
       return `feature/${featureId}`;
     }

     /** `<workspaceRoot>/docs/features/<featureId>/status.yaml` */
     export function statusYamlAbsPath(workspaceRoot: string, featureId: string): string {
       return join(workspaceRoot, "docs", "features", featureId, "status.yaml");
     }

     /** Relative path for git operations: `docs/features/<featureId>/status.yaml` */
     export function statusYamlRelPath(featureId: string): string {
       return join("docs", "features", featureId, "status.yaml");
     }
     ```

   - **`/agent/data/agent-workflow/runtime/orchestrator/src/feature-branch/lifecycle-manager.ts`** (new file)
