     export function ensureFeatureBranch(opts: EnsureFeatureBranchOpts): EnsureFeatureBranchResult {
       // 1. git fetch origin
       // 2. Check if feature branch exists on remote via git ls-remote --exit-code
       // 3a. If exists: git checkout -B "${featureBranch}" "origin/${featureBranch}"
       //     Compute merge-base for base SHA
       // 3b. If not exists: git checkout base → git pull → capture BASE_SHA → git checkout -b → git push -u
       // 4. Read status.yaml; write feature_branch and feature_branch_base_sha if unset
       //    NEVER overwrite feature_branch_base_sha (drift daemon baseline)
       // 5. Commit and push status.yaml changes to feature branch
     }

     export function runFeatureBranchLifecycle(opts: RunFeatureBranchLifecycleOpts): void {
       // Scans docs/features/ for all feature directories with status.yaml
       // Calls ensureFeatureBranch for each; errors per-feature are emitted, not thrown
     }
